<div class="page-header"><h2><?= $customer ? lang('edit_customer') : lang('add_customer') ?></h2></div><div class="card"><div class="card-body"><?= validation_errors('<div class="alert alert-danger">', '</div>') ?><?= form_open($customer ? 'customers/update/' . $customer['id'] : ($invoiceQuick ? 'customers/quick_store' : 'customers/store')) ?>
